107	static int translate_default_value(struct flb_config_map *map, char *val)
108	{
109	    int ret;
110	    struct flb_config_map_val *entry = NULL;
111	    struct mk_list *list = NULL;
112	
113	    /* Prepare contexts if the map allows multiple entries */
114	    if (map->flags & FLB_CONFIG_MAP_MULT) {
115	        entry = flb_calloc(1, sizeof(struct flb_config_map_val));
116	        if (!entry) {
117	            flb_errno();
118	            /*
119	             * do not worry about 'list' allocation, it will be destroyed by the caller
120	             * when it catches this error
121	             */
122	            return -1;
123	        }
124	    }
125	    else {
126	        entry = &map->value;
127	    }
128	
129	    /* Based on specific data types, populate 'value' */
130	    if (map->type == FLB_CONFIG_MAP_STR) {
131	        /* Duplicate string as a flb_sds_t */
132	        entry->val.str = flb_sds_create(val);
133	
134	        /* Validate new memory allocation */
135	        if (!entry->val.str) {
136	            goto error;
137	        }
138	    }
139	    else if (map->type == FLB_CONFIG_MAP_STR_PREFIX) {
140	        /*
141	         * For prefixed string types we don't process them, just validate
142	         * that no default value has been set.
143	         */
144	        if (val) {
145	            flb_error("[config map] invalid default value for prefixed string '%s'",
146	                      map->name);
147	            goto error;
148	        }
149	    }
150	    else if (map->type == FLB_CONFIG_MAP_BOOL) {
151	        ret = flb_utils_bool(val);
152	        if (ret == -1) {
153	            flb_error("[config map] invalid default value for boolean '%s=%s'",
154	                      map->name, val);
155	            goto error;
156	        }
157	        entry->val.boolean = flb_utils_bool(val);
158	    }
159	    else if (map->type == FLB_CONFIG_MAP_INT) {
160	        entry->val.i_num = atoi(val);
161	    }
162	    else if (map->type == FLB_CONFIG_MAP_DOUBLE) {
163	        entry->val.d_num = atof(val);
164	    }
165	    else if (map->type == FLB_CONFIG_MAP_SIZE) {
166	        entry->val.s_num = flb_utils_size_to_bytes(val);
167	    }
168	    else if (map->type == FLB_CONFIG_MAP_TIME) {
169	        entry->val.i_num = flb_utils_time_to_seconds(val);
170	    }
171	    else if (map->type >= FLB_CONFIG_MAP_CLIST &&
172	             map->type <= FLB_CONFIG_MAP_SLIST_4) {
173	
174	        list = parse_string_map_to_list(map, val);
175	        if (!list) {
176	            flb_error("[config map] cannot parse list of values '%s'", val);
177	            goto error;
178	        }
179	
180	        entry->val.list = list;
181	        list = NULL;
182	    }
183	
184	    if (map->flags & FLB_CONFIG_MAP_MULT) {
185	        mk_list_add(&entry->_head, map->value.mult);
186	    }
187	
188	    return 0;
189	
190	 error:
191	    if (map->flags & FLB_CONFIG_MAP_MULT) {
192	        flb_free(entry);
193	    }
194	    return -1;
195	}
