197	static flb_sds_t helper_map_options(struct mk_list *map)
198	{
199	    flb_sds_t buf;
200	    flb_sds_t tmp;
201	    struct mk_list *head;
202	    struct flb_config_map *m;
203	
204	    buf = flb_sds_create_size(256);
205	    if (!buf) {
206	        flb_errno();
207	        return NULL;
208	    }
209	
210	    tmp = flb_sds_printf(&buf, "The following properties are allowed: ");
211	    if (!tmp) {
212	        flb_errno();
213	        flb_sds_destroy(buf);
214	        return NULL;
215	    }
216	    buf = tmp;
217	
218	    mk_list_foreach(head, map) {
219	        m = mk_list_entry(head, struct flb_config_map, _head);
220	        if (head->next != map) {
221	            tmp = flb_sds_printf(&buf, "%s, ", m->name);
222	        }
223	        else {
224	            if (mk_list_size(map) == 1) {
225	                tmp = flb_sds_printf(&buf, "%s.", m->name);
226	            }
227	            else {
228	                tmp = flb_sds_printf(&buf, "and %s.", m->name);
229	            }
230	        }
231	
232	        if (!tmp) {
233	            flb_errno();
234	            flb_sds_destroy(buf);
235	            return NULL;
236	        }
237	        buf = tmp;
238	    }
239	
240	    return buf;
241	}
