243	/*
244	 * Given a static plugin configuration map, create a linked list representation. We use a
245	 * linked list using heap memory instead of the stack since a plugin can be loaded multiple
246	 * times.
247	 *
248	 * In addition, for default values, we process them and populate the 'value' field with
249	 * proper data types.
250	 */
251	struct mk_list *flb_config_map_create(struct flb_config *config,
252	                                      struct flb_config_map *map)
253	{
254	    int ret;
255	    flb_sds_t env;
256	    struct mk_list *tmp;
257	    struct mk_list *list;
258	    struct flb_config_map *new = NULL;
259	    struct flb_config_map *m;
260

251	struct mk_list *flb_config_map_create(struct flb_config *config,
252	                                      struct flb_config_map *map)
253	{
254	    int ret;
255	    flb_sds_t env;
256	    struct mk_list *tmp;
257	    struct mk_list *list;
258	    struct flb_config_map *new = NULL;
259	    struct flb_config_map *m;
260	
261	    list = flb_malloc(sizeof(struct mk_list));
262	    if (!list) {
263	        flb_errno();
264	        return NULL;
265	    }
266	    mk_list_init(list);
267	
268	    /*
269	     * Read every property defined in the config map and create a new dynamic list
270	     * with the same content.
271	     *
272	     * As an additional step, it populate the 'value' field using the given default
273	     * value if any. Note that default values are strings so they are processed
274	     * to fit into the proper data type of 'value'.
275	     */
276	    m = map;
277	    while (m && m->name) {
278	        /* Allocate map node */
279	        new = flb_calloc(1, sizeof(struct flb_config_map));
280	        if (!new) {
281	            flb_errno();
282	            flb_config_map_destroy(list);
283	            return NULL;
284	        }
285	
286	        new->type = m->type;
287	        new->name = flb_sds_create(m->name);
288	
289	        /* Translate default value */
290	        if (m->def_value) {
291	            /*
292	             * Before to translate any value, make sure to disable the warning
293	             * about unused variables. This might happen if a default value is an
294	             * environment variable and the user is not using it (which is ok for
295	             * that specific use case).
296	             */
297	            flb_env_warn_unused(config->env, FLB_FALSE);
298	
299	            /* Translate the value */
300	            env = flb_env_var_translate(config->env, m->def_value);
301	            new->def_value = env;
302	            flb_env_warn_unused(config->env, FLB_TRUE);
303	        }
304	
305	        new->flags = m->flags;
306	        new->set_property = m->set_property;
307	        new->offset = m->offset;
308	        new->value.mult = NULL;
309	        mk_list_add(&new->_head, list);
310	
311	        if (new->set_property == FLB_FALSE) {
312	            m++;
313	            continue;
314	        }
315	
316	        /* If this is a multiple type of entries, initialize the main list */
317	        if (new->flags & FLB_CONFIG_MAP_MULT) {
318	            tmp = flb_malloc(sizeof(struct mk_list));
319	            if (!tmp) {
320	                flb_errno();
321	                flb_config_map_destroy(list);
322	                return NULL;
323	            }
324	            mk_list_init(tmp);
325	            new->value.mult = tmp;
326	        }
327	
328	        /*
329	         * If there is no default value or the entry will not be set,  just
330	         * continue with the next map entry
331	         */
332	        if (!m->def_value) {
333	            m++;
334	            continue;
335	        }
336	
337	        /* Assign value based on data type and multiple mode if set */
338	        ret = translate_default_value(new, new->def_value);
339	        if (ret == -1) {
340	            flb_config_map_destroy(list);
341	            return NULL;
342	        }
343	        m++;
344	    }
345	
346	    return list;
347	}
