349	static void destroy_map_val(int type, struct flb_config_map_val *value)
350	{
351	    if (type == FLB_CONFIG_MAP_STR && value->val.str) {
352	        flb_sds_destroy(value->val.str);
353	    }
354	    else if ((type >= FLB_CONFIG_MAP_CLIST &&
355	              type <= FLB_CONFIG_MAP_SLIST_4) &&
356	             value->val.list) {
357	        flb_slist_destroy(value->val.list);
358	        flb_free(value->val.list);
359	    }
360	}
