362	/* Destroy a config map context */
363	void flb_config_map_destroy(struct mk_list *list)
364	{
365	    struct mk_list *tmp;
366	    struct mk_list *head;
367	    struct mk_list *v_head;
368	    struct mk_list *v_tmp;
369	    struct flb_config_map *map;
370	    struct flb_config_map_val *entry;
371	
372	    mk_list_foreach_safe(head, tmp, list) {
373	        map = mk_list_entry(head, struct flb_config_map, _head);
374	        mk_list_del(&map->_head);
375	
376	        if (map->flags & FLB_CONFIG_MAP_MULT && map->value.mult) {
377	            mk_list_foreach_safe(v_head, v_tmp, map->value.mult) {
378	                entry = mk_list_entry(v_head, struct flb_config_map_val, _head);
379	                mk_list_del(&entry->_head);
380	                destroy_map_val(map->type, entry);
381	                flb_free(entry);
382	            }
383	            flb_free(map->value.mult);
384	        }
385	        else {
386	            destroy_map_val(map->type, &map->value);
387	        }
388	        if (map->def_value) {
389	            flb_sds_destroy(map->def_value);
390	        }
391	        flb_sds_destroy(map->name);
392	        flb_free(map);
393	    }
394	    flb_free(list);
395	}
